class Solution:
    def lexicographicallySmallestArray(self, nums: List[int], limit: int) -> List[int]:
        n = len(nums)
        pairs = sorted((nums[i], i) for i in range(n))
        ans = [0] * n
        i = 0
        while i < n:
            j = i + 1
            while j < n and pairs[j][0] - pairs[j - 1][0] <= limit:
                j += 1
            indices = sorted(pairs[k][1] for k in range(i, j))
            for k, idx in enumerate(indices):
                ans[idx] = pairs[i + k][0]
            i = j
        return ans

class Solution {
public:
    vector<int> lexicographicallySmallestArray(vector<int>& nums, int limit) {
        int n = nums.size();
        vector<pair<int, int>> pairs(n);
        for (int i = 0; i < n; i++) pairs[i] = {nums[i], i};
        sort(pairs.begin(), pairs.end());
        vector<int> ans(n);
        int i = 0;
        while (i < n) {
            int j = i + 1;
            while (j < n && pairs[j].first - pairs[j - 1].first <= limit) j++;
            vector<int> indices;
            for (int k = i; k < j; k++) indices.push_back(pairs[k].second);
            sort(indices.begin(), indices.end());
            for (int k = 0; k < indices.size(); k++) {
                ans[indices[k]] = pairs[i + k].first;
            }
            i = j;
        }
        return ans;
    }
};

class Solution {
    public int[] lexicographicallySmallestArray(int[] nums, int limit) {
        int n = nums.length;
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums[i];
            pairs[i][1] = i;
        }
        Arrays.sort(pairs, (a, b) -> Integer.compare(a[0], b[0]));
        int[] ans = new int[n];
        int i = 0;
        while (i < n) {
            int j = i + 1;
            while (j < n && pairs[j][0] - pairs[j - 1][0] <= limit) j++;
            int[] indices = new int[j - i];
            for (int k = i; k < j; k++) indices[k - i] = pairs[k][1];
            Arrays.sort(indices);
            for (int k = 0; k < indices.length; k++) {
                ans[indices[k]] = pairs[i + k][0];
            }
            i = j;
        }
        return ans;
    }
}

